// ─── SINGLE-FILE BUNDLER ─────────────────────────────────────────────────────
//
// Collapses the development tree (wolf3d.html + wolf3d/*.js + wolf3d/style.css)
// into one self-contained dist/wolf3d.html: CSS inlined into a <style>, every
// local script concatenated into one inline <script>.
//
//   node reference/bundle.js                 # -> dist/wolf3d.html
//   node reference/bundle.js --check         # exit 1 if dist is stale
//
// This is forty lines of string joining rather than a bundler because the split
// is classic scripts sharing one script scope. Concatenating them in document
// order is not an approximation of the split build — it is the same program in
// the same scope. Nothing is renamed, hoisted, wrapped or tree-shaken, which is
// why the same test suite can run against both representations and mean
// something.
//
// The Google Fonts <link> is left alone: it is the one external request the
// game makes, and inlining it is neither possible nor wanted.

'use strict';

const fs = require('fs');
const path = require('path');
const { collectSources } = require('./harness');

const ROOT = path.join(__dirname, '..');
const SRC  = path.join(ROOT, 'wolf3d.html');
const OUT  = path.join(ROOT, 'dist', 'wolf3d.html');

const BANNER =
  '<!-- GENERATED by reference/bundle.js from wolf3d.html + wolf3d/. Do not edit:\n' +
  '     changes here are lost on the next build. Edit the source tree instead. -->';

function bundle(srcPath) {
  const dir = path.dirname(srcPath);
  let html = fs.readFileSync(srcPath, 'utf8');

  // 1. Inline local stylesheets, leave remote ones (the fonts) in place.
  html = html.replace(/<link\b[^>]*\brel\s*=\s*["']stylesheet["'][^>]*>/gi, tag => {
    const href = (tag.match(/\bhref\s*=\s*["']([^"']+)["']/) || [])[1];
    if (!href || /^https?:/i.test(href)) return tag;
    const css = fs.readFileSync(path.resolve(dir, href), 'utf8').replace(/\n+$/, '');
    return '<style>\n' + css + '\n</style>';
  });

  // 2. Replace the run of <script> tags with one inline block. collectSources
  //    is the same walk the harness uses, so the manifest's tag order stays the
  //    single declaration of load order.
  const code = collectSources(srcPath).map(s => s.code).join('\n;\n');
  let first = true;
  html = html.replace(/<script\b([^>]*)>([\s\S]*?)<\/script>/g, (tag, attrs) => {
    const src = (attrs.match(/\bsrc\s*=\s*["']([^"']+)["']/) || [])[1];
    if (src && /^https?:/i.test(src)) return tag;   // external: untouched
    if (!first) return '';                          // folded into the first
    first = false;
    return '<script>\n' + code.replace(/^\n+|\n+$/g, '') + '\n</script>';
  });

  return BANNER + '\n' + html.replace(/\n{3,}/g, '\n\n');
}

function main() {
  const out = bundle(SRC);
  const check = process.argv.includes('--check');
  const current = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : null;

  if (check) {
    if (current === out) { console.log('dist/wolf3d.html is current'); process.exit(0); }
    console.error(current === null
      ? 'dist/wolf3d.html does not exist — run: node reference/bundle.js'
      : 'dist/wolf3d.html is STALE — run: node reference/bundle.js');
    process.exit(1);
  }

  fs.mkdirSync(path.dirname(OUT), { recursive: true });
  fs.writeFileSync(OUT, out);
  const kb = n => (n / 1024).toFixed(1) + ' KB';
  console.log('dist/wolf3d.html  ' + out.split('\n').length + ' lines  ' + kb(Buffer.byteLength(out)) +
              (current === out ? '  (unchanged)' : ''));
}

if (require.main === module) main();
module.exports = { bundle, SRC, OUT };
